import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';
import { ThemeToggle } from './ThemeToggle';
import { useThemeStore } from '../state/themeStore';

jest.mock('../state/themeStore');
const mockedUseThemeStore = jest.mocked(useThemeStore);

describe('ThemeToggle', () => {
  beforeEach(() => {
    mockedUseThemeStore.mockReset();
  });

  it('renderiza com tema claro por padrão', () => {
    mockedUseThemeStore.mockReturnValue({ theme: 'light', toggle: jest.fn() });
    render(<ThemeToggle />);

    expect(screen.getByRole('button', { name: 'Ativar tema claro' })).toBeInTheDocument();
    expect(document.documentElement).toHaveAttribute('data-theme', 'light');
  });

  it('alterna para tema escuro ao clicar', async () => {
    const toggleMock = jest.fn(() => {
      mockedUseThemeStore.mockReturnValue({ theme: 'dark', toggle: toggleMock });
    });
    mockedUseThemeStore.mockReturnValue({ theme: 'light', toggle: toggleMock });
    render(<ThemeToggle />);

    await userEvent.click(screen.getByRole('button', { name: 'Ativar tema claro' }));

    expect(toggleMock).toHaveBeenCalled();
    await waitFor(() => {
      expect(screen.getByRole('button', { name: 'Ativar tema escuro' })).toBeInTheDocument();
      expect(document.documentElement).toHaveAttribute('data-theme', 'dark');
    });
  });

  it('alterna para tema claro ao clicar', async () => {
    const toggleMock = jest.fn(() => {
      mockedUseThemeStore.mockReturnValue({ theme: 'light', toggle: toggleMock });
    });
    mockedUseThemeStore.mockReturnValue({ theme: 'dark', toggle: toggleMock });
    render(<ThemeToggle />);

    await userEvent.click(screen.getByRole('button', { name: 'Ativar tema escuro' }));

    expect(toggleMock).toHaveBeenCalled();
    await waitFor(() => {
      expect(screen.getByRole('button', { name: 'Ativar tema claro' })).toBeInTheDocument();
      expect(document.documentElement).toHaveAttribute('data-theme', 'light');
    });
  });

  it('atributo data-theme é atualizado no documento', () => {
    mockedUseThemeStore.mockReturnValue({ theme: 'dark', toggle: jest.fn() });
    render(<ThemeToggle />);

    expect(document.documentElement).toHaveAttribute('data-theme', 'dark');
  });

  it('caso de borda: tema inicial inválido', () => {
    mockedUseThemeStore.mockReturnValue({ theme: 'unknown', toggle: jest.fn() });
    render(<ThemeToggle />);

    expect(screen.getByRole('button', { name: 'Ativar tema claro' })).toBeInTheDocument();
    expect(document.documentElement).not.toHaveAttribute('data-theme', 'unknown');
  });
});
